import React, { useEffect, useState } from 'react';
import './Header.css';  // Make sure to import the CSS for the Header component

const Header = () => {
    const [headerStyle, setHeaderStyle] = useState({});

    useEffect(() => {
        const handleScroll = () => {
            const scrollProgress = Math.min(window.scrollY / 20, 1); // Ensure the value is between 0 and 1
            // Example: Adjusting opacity based on scroll progress
            // You can add more style changes based on scrollProgress
            setHeaderStyle({
                backgroundColor: `rgba(255, 250, 241, ${scrollProgress})`, // Example for background color
                boxShadow: `0 4px 30px rgba(0, 0, 0, )`, // Example for box-shadow
            });
        };

        window.addEventListener('scroll', handleScroll);

        // Cleanup function to remove the event listener
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    return (
        <header id='header' style={headerStyle}>
            <nav>
                <ul>
                    <li><a href="#intro">Intro</a></li>
                    <li><a href="#about">About Me</a></li>
                    <li><a href="#skills">Skills</a></li>
                    <li><a href="#contact">Contact</a></li>
                </ul>
            </nav>
        </header>
    );
};

export default Header;
